from typing import Any, Dict, Mapping
from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location
from stockflow.parse_quantity import parse_quantity

def parse_movement_line(line: str, case_sizes: Mapping[str, int]) -> Dict[str, Any]:
    f = [x.strip() for x in line.split(';')] 
    if len(f) != 5: raise ValueError('err')
    try:
        d = int(f[0])
        if d < 0: raise ValueError()
    except: raise ValueError('err')
    t = f[1].upper()
    if t not in ('RCV', 'SHP', 'RTN', 'ADJ'): raise ValueError('err')
    s = normalize_sku(f[2])
    z, a, sh, l = parse_location(f[3])
    loc = f'{z}-{a:02d}-{sh:02d}-{l}'
    q = parse_quantity(f[4], case_sizes.get(s, 1))
    if t == 'SHP': q = -abs(q)
    elif t in ('RCV', 'RTN'): q = abs(q)
    return {'day': d, 'type': t, 'sku': s, 'location': loc, 'qty': q}"
  }
}
